private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        throw new IllegalArgumentException("Cannot rotate right: node or its left child is null.");
    }
    TreeNode<T> left = node.left;
    // Perform rotation
    node.left = left.right;
    if (left.right != null) {
        left.right.parent = node;
    }
    left.right = node;
    left.parent = node.parent;
    node.parent = left;
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> pivot = node.left; // node to become new parent
    if (pivot == null) {
        // cannot perform rotation
        return node;
    }
    try {
        // Reattach pivot's right subtree as node's left subtree
        node.left = pivot.right;
        if (pivot.right != null) {
            pivot.right.parent = node;
        }
        // Make node a child of pivot
        pivot.right = node;
        pivot.parent = node.parent;
        node.parent = pivot;

        // Update grandparent's link if necessary
        if (pivot.parent != null) {
            if (pivot.parent.left == node) {
                pivot.parent.left = pivot;
            } else if (pivot.parent.right == node) {
                pivot.parent.right = pivot;
            }
        }
        return pivot;
    } catch (Exception e) {
        // In case of any runtime issue, return the original node
        return node;
    }
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // If the node or its left child is null, rotation cannot be performed
    if (node == null || node.left == null) {
        return node;
    }

    TreeNode<T> parent = node.parent;          // Store the current parent
    TreeNode<T> leftChild = node.left;         // Node that will become the new parent
    TreeNode<T> leftRight = leftChild.right;   // This child will become node.left later

    // Perform the rotation
    node.left = leftRight;
    if (leftRight != null) {
        leftRight.parent = node;
    }

    leftChild.right = node;
    node.parent = leftChild;

    // Update the old parent to point to the new parent (leftChild)
    if (parent != null) {
        if (parent.left == node) {
            parent.left = leftChild;
        } else if (parent.right == node) {
            parent.right = leftChild;
        }
    }

    leftChild.parent = parent;
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("node must not be null");
    }

    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        throw new IllegalArgumentException("node has no left child; cannot perform right rotation");
    }

    // detach left child's right subtree and attach it to node's left
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    // make node the right child of its former left child
    leftChild.right = node;

    // update parent references
    leftChild.parent = node.parent;
    node.parent = leftChild;

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    // Safety check: if the node or its left child is null, rotation cannot be performed
    if (node == null || node.left == null) {
        return node;
    }
    try {
        TreeNode<T> leftChild = node.left;
        // Detach leftChild's right subtree and attach it as node's left subtree
        node.left = leftChild.right;
        if (leftChild.right != null) {
            leftChild.right.parent = node;
        }
        // Reattach node as the right child of leftChild
        leftChild.right = node;
        leftChild.parent = node.parent;
        node.parent = leftChild;

        // Update the parent reference of leftChild in the original parent, if any
        if (leftChild.parent != null) {
            if (leftChild.parent.left == node) {
                leftChild.parent.left = leftChild;
            } else if (leftChild.parent.right == node) {
                leftChild.parent.right = leftChild;
            }
        }
        return leftChild;
    } catch (Exception e) {
        // In case of any unexpected runtime issues, propagate as a runtime exception
        throw new RuntimeException("Error performing right rotation", e);
    }
}

