        String pat = this.pattern;
        if (pat == null || pat.isEmpty()) {
            pat = "%m%n";
        }
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < pat.length()) {
            char c = pat.charAt(i);
            if (c == '%' && i + 1 < pat.length()) {
                char spec = pat.charAt(i + 1);
                switch (spec) {
                    case 'd':
                        out.append(new java.util.Date(event.getTimeStamp()).toString());
                        i += 2;
                        break;
                    case 'p':
                        out.append(event.getLevel().toString());
                        i += 2;
                        break;
                    case 'c':
                        out.append(event.getLoggerName());
                        i += 2;
                        break;
                    case 'm':
                        out.append(event.getFormattedMessage());
                        i += 2;
                        break;
                    case 'n':
                        out.append(System.lineSeparator());
                        i += 2;
                        break;
                    case '%':
                        out.append('%');
                        i += 2;
                        break;
                    default:
                        // Unrecognized specifier, copy literally
                        out.append(c);
                        i++;
                        break;
                }
            } else {
                out.append(c);
                i++;
            }
        }
        return out.toString();
    } catch (Exception e) {
        // Return a simple fallback if formatting fails
        return event != null ? event.getFormattedMessage() : "";
    }
