            String stackStr = stack.toString();
            result = result.replaceAll("%ex", stackStr);
            result = result.replaceAll("%throwable", stackStr);
        }

        return result;
    } catch (Exception e) {
        // Fallback to the event message on any formatting error.
        return event.getMessage() != null ? event.getMessage() : "";
    }
