protected void subAppend(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("event cannot be null");
    }
    try {
        String message;
        try {
            message = (event.getMessage() != null) ? event.getMessage().toString() : "null";
        } catch (Throwable t) {
            message = "<error rendering message>";
        }

        String level = (event.getLevel() != null) ? event.getLevel().toString() : "UNKNOWN";
        String loggerName = (event.getLoggerName() != null) ? event.getLoggerName() : "UNKNOWN";

        String timestamp = new java.util.Date(event.getTimeStamp()).toString();

        String output = String.format("%s [%s] %s - %s", timestamp, level, loggerName, message);

        System.out.println(output);
    } catch (Throwable t) {
        System.err.println("Error while appending LoggingEvent: " + t);
        t.printStackTrace(System.err);
    }
}

protected void subAppend(LoggingEvent event){
        if (event == null){
            // Nothing to write
            return;
        }
        try {
            // Attempt to retrieve a readable representation of the event
            String rendered = event.getRenderedMessage();
            if (rendered == null) {
                Object msgObj = event.getMessage();
                rendered = (msgObj != null) ? msgObj.toString() : "";
            }
            // Write the message to the intended output (here standard out)
            System.out.println(rendered);
        } catch (Throwable t) {
            // Preserve the runtime integrity by catching all Throwables
            // and printing a diagnostic message to standard error
            System.err.println("subAppend failed: " + t.getMessage());
            t.printStackTrace();
        }
    }

protected void subAppend(LoggingEvent event){
    if (event == null){
        return;
    }
    synchronized (this){
        try{
            String msg = (layout == null) ? event.getMessage() : layout.format(event);
            if(writer != null){
                writer.write(msg);
                writer.write(System.lineSeparator());
                writer.flush();
            }
        }catch(IOException e){
            if(errorHandler != null){
                errorHandler.error("Failed to write log message", e, ErrorHandler.ErrorCode.WRITE_FAILURE);
            }
        }
    }
}

protected void subAppend(LoggingEvent event){
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        // Attempt to write the formatted message to standard output.
        // Concrete subclasses can override this to write to a file or other destination.
        String message = event.getFormattedMessage();
        System.out.println(message != null ? message : event.getMessage().toString());
    } catch (Exception e) {
