int addType(final String value){
    if (value == null) {
        throw new IllegalArgumentException("value cannot be null");
    }
    // ensure the type table exists
    if (typeTable == null) {
        typeTable = new java.util.ArrayList<>();
    }
    // search for existing entry
    for (int i = 0; i < typeTable.size(); i++) {
        Symbol sym = typeTable.get(i);
        if (sym != null && value.equals(sym.getValue())) {
            return i; // already present
        }
    }
    // add new type symbol
    Symbol newSym = new Symbol(value); // assuming Symbol has a constructor that takes the value
    typeTable.add(newSym);
    return typeTable.size() - 1; // index of the newly added type
}

