public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof java.lang.reflect.ParameterizedType)) {
        return null;
    }
    java.lang.reflect.ParameterizedType pType = (java.lang.reflect.ParameterizedType) genericType;
    java.lang.reflect.Type[] args = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Class<?> resolved = resolveType(args[i], targetType);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

private static Class<?> resolveType(java.lang.reflect.Type type, Class<?> targetType) {
    if (type instanceof Class) {
        return (Class<?>) type;
    }
    if (type instanceof java.lang.reflect.ParameterizedType) {
        java.lang.reflect.Type raw = ((java.lang.reflect.ParameterizedType) type).getRawType();
        if (raw instanceof Class) {
            return (Class<?>) raw;
        }
    }
    if (type instanceof java.lang.reflect.TypeVariable) {
        return resolveTypeVariable((java.lang.reflect.TypeVariable<?>) type, targetType);
    }
    return null;
}

private static Class<?> resolveTypeVariable(java.lang.reflect.TypeVariable<?> var, Class<?> targetType) {
    java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> typeMap = new java.util.HashMap<>();
    buildTypeMapping(targetType, typeMap);
    java.lang.reflect.Type resolved = typeMap.get(var);
    if (resolved instanceof Class) {
        return (Class<?>) resolved;
    }
    if (resolved instanceof java.lang.reflect.ParameterizedType) {
        java.lang.reflect.Type raw = ((java.lang.reflect.ParameterizedType) resolved).getRawType();
        if (raw instanceof Class) {
            return (Class<?>) raw;
        }
    }
    return null;
}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    try {
        // Attempt to merge with existing entry if present
        METRICS existing = cache.get(data.getKey());
        if (existing != null) {
            // If METRICS implements a merge method, use it; otherwise, fallback to new value
            try {
                java.lang.reflect.Method mergeMethod = data.getClass().getMethod("merge", data.getClass());
                @SuppressWarnings("unchecked")
                METRICS merged = (METRICS) mergeMethod.invoke(data, existing);
                cache.put(data.getKey(), merged);
            } catch (NoSuchMethodException | SecurityException e) {
                // No merging support; replace the old value
                cache.put(data.getKey(), data);
            } catch (Exception e) {
                // If merge invocation fails, replace the old value
                cache.put(data.getKey(), data);
            }
        } else {
            cache.put(data.getKey(), data);
        }
    } catch (Exception e) {
        // The method is not thread–safe; ignore unexpected runtime issues
    }
}

@Override
public void accept(final METRICS data){
    if (data == null) {
        return;
    }
    try {
        /* If the cache map is not initialized, we can't store the data. */
        if (cache == null) {
            throw new IllegalStateException("The metrics cache has not been initialized.");
        }

        /* Use the data object itself as the key.  This can be
         * overridden if the METRICS class provides a getKey()
         * or similar method that returns a better lookup key. */
        java.lang.Object key = data;
        try {
            java.lang.Object k = data.getClass().getMethod("getKey").invoke(data);
            if (k != null) {
                key = k;
            }
        } catch (Throwable ignored) {
            /* Fine: keep default key. */
        }

        METRICS existing = cache.get(key);
        if (existing != null) {
            /* Try to merge using a mergeWith(METRICS) method if one exists. */
            METRICS merged = null;
            try {
                java.lang.reflect.Method m = data.getClass().getMethod("mergeWith", data.getClass());
                Object r = m.invoke(data, existing);
                if (r != null) {
                    merged = data.getClass().cast(r);
                }
            } catch (Throwable ignored) {
                /* Fallback to simply replacing the existing value. */
            }
            if (merged != null) {
                cache.put(key, merged);
            } else {
                cache.put(key, data);
            }
        } else {
            cache.put(key, data);
        }
    } catch (Throwable t) {
        /* Wrap any exception in an unchecked exception so callers
         * are aware that the accept operation failed. */
        throw new IllegalArgumentException("Failed to accept and merge metric data.", t);
    }
}

public void accept(final METRICS data) {
    if (data == null) {
        throw new IllegalArgumentException("METRICS data cannot be null");
    }
    try {
        // Attempt to get an existing entry that matches the incoming data.
        // The cache is expected to use equals()/hashCode() of METRICS for key lookup.
        METRICS existing = this.cache.get(data);
        if (existing != null) {
            // Merge the incoming data into the existing entry.
            // It is assumed that METRICS has a merge(METRICS) method that updates the instance.
            existing.merge(data);
        } else {
            // No existing entry: simply store the new data.
            this.cache.put(data, data);
        }
    } catch (Exception ex) {
        // Wrap any unexpected runtime exception; the method is intentionally not thread‑safe.
        throw new RuntimeException("Failed to accept METRICS into cache", ex);
    }
}

