public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (tableName == null || tableName.isEmpty()) {
            throw new IllegalArgumentException("tableName must not be null or empty");
        }
        if (mappings == null) {
            throw new IllegalArgumentException("mappings must not be null");
        }

        // Retrieve the current mapping of the index corresponding to the tableName.
        // This is assumed to be provided by an existing helper method.
        Mappings current = getCurrentMappings(tableName);
        if (current == null) {
            return new Mappings();
        }

        // Prepare a mapping containing only the fields that are present in the current
        // mapping but not in the history mapping supplied as a parameter.
        Mappings diff = new Mappings();
        for (String field : current.keySet()) {
            // Skip the _source configuration to avoid update conflicts.
            if ("_source".equals(field)) {
                continue;
            }
            if (!mappings.containsKey(field)) {
                diff.put(field, current.get(field));
            }
        }
        return diff;
    } catch (Exception e) {
        // In case of any error, log the exception if logging is available
        // and return an empty mapping to ensure graceful degradation.
        return new Mappings();
    }
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Validate inputs
    if (tableName == null || tableName.trim().isEmpty()) {
        throw new IllegalArgumentException("tableName must not be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("mappings must not be null");
    }

    // We assume Mappings implements Map<String,Object> interface.
    // Create a new mapping instance without the "_source" field.
    // This will avoid current index update conflict as requested.
    try {
        @SuppressWarnings("unchecked")
        java.util.Map<String, Object> originalMap = (java.util.Map<String, Object>) mappings;
        java.util.Map<String, Object> filteredMap = new java.util.HashMap<>();
        for (java.util.Map.Entry<String, Object> entry : originalMap.entrySet()) {
            if (!"_source".equals(entry.getKey())) {
                filteredMap.put(entry.getKey(), entry.getValue());
            }
        }
        // Create a new Mappings object from the filtered map.
        // If Mappings does not have a suitable constructor, use the default one and putAll.
        try {
            Mappings result;
            // Attempt to use a constructor that accepts a map
            java.lang.reflect.Constructor<?> ctor = Mappings.class.getConstructor(java.util.Map.class);
            result = (Mappings) ctor.newInstance(filteredMap);
            return result;
        } catch (NoSuchMethodException e) {
            // Fallback: use default constructor and populate the map
            Mappings result = Mappings.class.newInstance();
            if (result instanceof java.util.Map) {
                java.util.Map<String, Object> resultMap = (java.util.Map<String, Object>) result;
                resultMap.putAll(filteredMap);
            } else {
                // If Mappings doesn't support putAll, return the filtered map casted as Mappings
                // This is a best-effort fallback; if casting invalid, will throw ClassCastException.
                return (Mappings) filteredMap;
            }
            return result;
        }
    } catch (Exception e) {
        // In case of any reflection or cast issues, fall back to returning an empty mapping.
        // Using default constructor if available.
        try {
            return Mappings.class.newInstance();
        } catch (Exception ex) {
            throw new RuntimeException("Failed to create diff mapping", e);
        }
    }
}

public Mappings diffStructure(String tableName,Mappings mappings){
    try {
        if (mappings == null) {
            return new Mappings();
        }
        // Attempt to retrieve the historical mapping for the given table.
        // This implementation assumes a placeholder repository that returns a Mappings instance.
        Mappings historical = MappingRepository.getHistoricalMapping(tableName);
        if (historical == null) {
            // No historical mapping available; nothing to diff.
            return new Mappings();
        }

        java.util.Map<String, Object> oldMap = historical.toMap();
        java.util.Map<String, Object> inputMap = mappings.toMap();

        java.util.Map<String, Object> diffMap = new java.util.LinkedHashMap<>();
        for (java.util.Map.Entry<String, Object> entry : oldMap.entrySet()) {
            String field = entry.getKey();
            if ("_source".equals(field)) {
                // Skip _source field to avoid index update conflict.
                continue;
            }
            if (!inputMap.containsKey(field)) {
                diffMap.put(field, entry.getValue());
            }
        }
        return Mappings.fromMap(diffMap);
    } catch (Exception e) {
        // Log the exception details if a logger is available; otherwise rethrow as runtime.
        // For the purpose of this method, wrap and throw a runtime exception.
        throw new RuntimeException("Failed to compute diff for table: " + tableName, e);
    }
}

