public static void createConfigurationDirectory() {
    String dirPath;
    String os = System.getProperty("os.name");
    if (os != null && os.contains("Windows 2000")) {
        // Attempt to use the system drive environment variable
        String systemDrive = System.getenv("SYSTEMDRIVE");
        if (systemDrive == null) {
            systemDrive = "C:\\";
        }
        // Ensure backslash at the end
        if (!systemDrive.endsWith("\\")) {
            systemDrive += "\\";
        }
        dirPath = systemDrive + "Documents and Settings" + File.separator + "lf5";
    } else {
        String userHome = System.getProperty("user.home");
        if (userHome == null || userHome.isEmpty()) {
            // Fallback to root directory if user.home is not available
            userHome = System.getProperty("java.io.tmpdir", ".")
                           .replace("\\", File.separator);
        }
        dirPath = userHome + File.separator + "lf5";
    }

    File dir = new File(dirPath);
    if (!dir.exists()) {
        try {
            boolean created = dir.mkdirs();
            if (!created && !dir.exists()) {
                throw new RuntimeException("Failed to create directory: " + dirPath);
            }
        } catch (SecurityException se) {
