    // If no message or no clients, just return
    if (message == null || clientOutputs == null || clientOutputs.isEmpty()) {
        return;
    }

    // Telnet protocols typically use CRLF as line terminators
    final String telnetMessage = message + "\r\n";

    // Use an iterator to allow safe removal of faulty streams
    Iterator<PrintWriter> it = clientOutputs.iterator();
    while (it.hasNext()) {
        PrintWriter out = it.next();
        try {
            out.print(telnetMessage);
            out.flush();
        } catch (Exception e) {
            // Remove broken connection and close its stream
            it.remove();
            try {
                out.close();
            } catch (Exception ignored) {
                // Ignored – cleanup failure should not crash the server
            }
        }
    }
}

public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    final String telnetMessage = message + "\r\n";
    // Use an iterator to safely remove a client while iterating
    final java.util.Iterator<?> it = clients.iterator();
    while (it.hasNext()) {
        final Object obj = it.next();
        try {
            if (obj instanceof TelnetClient) {
                ((TelnetClient) obj).send(telnetMessage);
            } else if (obj instanceof java.net.Socket) {
                final java.net.Socket sock = (java.net.Socket) obj;
                java.io.PrintWriter out = new java.io.PrintWriter(sock.getOutputStream(), true);
                out.print(telnetMessage);
                out.flush();
            } else {
                // Unknown client type – skip
                continue;
            }
        } catch (Exception e) {
            // If sending fails, close the client and remove it from the list
            try {
                if (obj instanceof TelnetClient) {
                    ((TelnetClient) obj).disconnect();
                } else if (obj instanceof java.net.Socket) {
                    ((java.net.Socket) obj).close();
                }
            } catch (Exception ignore) {
                // ignore errors during cleanup
            }
            it.remove();
        }
    }
}

public synchronized void send(final String message){
    if (message == null){
        throw new IllegalArgumentException("message cannot be null");
    }
    String telnetMsg = message.replace("\n", "\r\n");
    if (clients == null){
        return;
    }
    for (java.io.PrintWriter out : clients){
        try{
            out.print(telnetMsg);
            out.flush();
        }catch (Exception e){
            // ignore failures for individual clients
        }
    }
}

