protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    try {
        for (long current = start; current < end; ) {
            long rangeEnd = current + FETCH_DATA_DURATION - 1;
            // Handle potential overflow
            if (rangeEnd < 0 || rangeEnd > end) {
                rangeEnd = end;
            }
            ranges.add(new TimeRange(current, rangeEnd));
            current = rangeEnd + 1;
        }
    } catch (RuntimeException e) {
        // In case TimeRange constructor or other operations throw an exception,
        // return an empty list to avoid propagating the error.
        return new ArrayList<>();
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Validate inputs
    if (start < 0 || end < 0) {
        // Negative timestamps are considered invalid; return an empty list
        return ranges;
    }
    if (start >= end || FETCH_DATA_DURATION <= 0) {
        // Zero or negative duration or empty interval yields no ranges
        return ranges;
    }

    long current = start;
    while (current < end) {
        long next;
        if (FETCH_DATA_DURATION > 0 && current > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            // Prevent overflow by clamping to MAX_VALUE
            next = end;
        } else {
            next = current + FETCH_DATA_DURATION;
            if (next > end || next <= 0) {
                next = end; // Ensure we don't cross the end boundary
            }
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate inputs
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative. Received start=" + start + ", end=" + end);
    }
    if (end < start) {
        throw new IllegalArgumentException("End time must be greater than or equal to start time. Received start=" + start + ", end=" + end);
    }
    // If FETCH_DATA_DURATION is not set or non-positive, we cannot split appropriately
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive to split time ranges.");
    }
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();

    if (start == end) {
        // Empty interval – nothing to split
        return ranges;
    }

    long rangeStart = start;
    while (rangeStart < end) {
        long possibleEnd = rangeStart + FETCH_DATA_DURATION;
        long rangeEnd = Math.min(possibleEnd, end);
        ranges.add(new TimeRange(rangeStart, rangeEnd));
        rangeStart = rangeEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time.");
    }

    List<TimeRange> ranges = new ArrayList<>();

    // If the duration is non-positive, treat the whole interval as one range
    if (FETCH_DATA_DURATION <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }

    // Handle zero-length interval explicitly
    if (start == end) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }

    long current = start;
    while (current < end) {
        long rangeEnd = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, rangeEnd));
        current = rangeEnd;
    }

    return ranges;
}

