        long nextEnd;
        // Prevent overflow when adding FETCH_DATA_DURATION
        if (FETCH_DATA_DURATION > 0 && current > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            nextEnd = end;
        } else {
            nextEnd = Math.min(current + FETCH_DATA_DURATION, end);
        }
        if (nextEnd == current) {
            // Should not happen, but guard against infinite loop
            break;
        }
        ranges.add(new TimeRange(current, nextEnd));
        current = nextEnd;
    }
    return ranges;
}

