static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    // Basic range check for an 8-digit date in the form YYYYMMDD
    if(timeBucket < 10000101L || timeBucket > 99991231L){
        throw new IllegalArgumentException("timeBucket is not a valid 8-digit date");
    }
    int year  = (int)(timeBucket / 10000);
    int monthDay = (int)(timeBucket % 10000);
    int month = monthDay / 100;
    int day   = monthDay % 100;
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("month must be between 01 and 12");
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("day must be between 01 and 31");
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Extract year, month, day
    long year = timeBucket / 10000L;
    long month = (timeBucket / 100L) % 100L;
    long day = timeBucket % 100L;

    // Basic validation of month and day
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    // Optionally validate day against month length (simplified leap year check)
    int[] monthLength = {0,31,28,31,30,31,30,31,31,30,31,30,31};
    if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
        monthLength[2] = 29;
    }
    if (day > monthLength[(int)month]) {
        throw new IllegalArgumentException("Day " + day + " exceeds the length of month " + month);
    }

    // Compute the start day of the group that contains the original day
    long startDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the compressed time bucket
    return year * 10000L + month * 100L + startDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
