    int[] monthLengths = {0,31,28,31,30,31,30,31,31,30,31,30,31};
    int maxDay = monthLengths[(int) month];
    // Adjust for February leap years
    if (month == 2) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            maxDay = 29;
        }
    }
    if (day < 1 || day > maxDay) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    // Compute the reformatted day
    long newDay = 1 + ((day - 1) / dayStep) * dayStep;
    // Ensure newDay does not exceed month length (it should not with integer division)
    if (newDay > maxDay) {
        newDay = maxDay;
    }

    // Reassemble the new time bucket
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive.");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than zero.");
    }
    // Extract year, month, day
    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;

    // Basic month/year/day validation
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    int daysInMonth;
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31; break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30; break;
        case 2:
            boolean isLeap = (year % 4 == 0) && ((year % 100 != 0) || (year % 400 == 0));
            daysInMonth = isLeap ? 29 : 28; break;
        default:
            throw new IllegalArgumentException("Unexpected month: " + month);
    }
    if (day < 1 || day > daysInMonth) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    // Compute new day within the bucket period
    int newDay = (int) (((day - 1) / dayStep) * dayStep + 1);

    long newTimeBucket = (long) year * 10000 + (long) month * 100 + newDay;
    return newTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non‑negative");
    }
    if (index > str.length() - len) {
        throw new IllegalArgumentException("Index + length exceeds string bounds");
    }
    int byteCount = 0;
    try {
        int end = index + len;
        int i = index;
        while (i < end) {
            char c = str.charAt(i);
            if (c <= 0x007F) {
                byteCount += 1;
            } else if (c <= 0x07FF) {
                byteCount += 2;
            } else if (Character.isHighSurrogate(c)) {
                if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                    // Valid surrogate pair => U+10000 to U+10FFFF
                    byteCount += 4;
                    i++; // Skip the low surrogate
                } else {
                    // Unmatched high surrogate; treat as 3 bytes (ISO-10646 UTF‑8)
                    byteCount += 3;
                }
            } else if (Character.isLowSurrogate(c)) {
                // Unmatched low surrogate; treat as 3 bytes
                byteCount += 3;
            } else {
                byteCount += 3;
            }
            i++;
        }
    } catch (Exception e) {
        // Unexpected runtime error; wrap and rethrow as unchecked exception
        throw new RuntimeException("Error computing UTF‑8 size", e);
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String must not be null");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException("Invalid index or length for the specified CharSequence");
    }
    int end = index + len;
    int utf8Len = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            utf8Len += 1;
            i++;
        } else if (ch < 0x800) {
            utf8Len += 2;
            i++;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Valid surrogate pair -> 4 bytes
                utf8Len += 4;
                i += 2;
            } else {
                // Unpaired high surrogate -> encode as 3 bytes (replacement)
                utf8Len += 3;
                i++;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate -> encode as 3 bytes
            utf8Len += 3;
            i++;
        } else {
            // BMP character that requires 3 bytes
            utf8Len += 3;
            i++;
        }
    }
    return utf8Len;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index or length out of bounds");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char l = str.charAt(i + 1);
            if (Character.isLowSurrogate(l)) {
                codePoint = Character.toCodePoint(ch, l);
                i += 2;
            } else {
                // malformed surrogate pair
                codePoint = 0xFFFD;  // replacement character
                i += 1;
            }
        } else {
            codePoint = ch;
            i += 1;
        }

        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else if (codePoint <= 0x10FFFF) {
            size += 4;
        } else {
            // invalid code point, fallback to replacement character size
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String sequence is null");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException(
                "Index " + index + " with length " + len + " exceeds string bounds");
    }
    int size = 0;
    int end = index + len;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
            i++;
        } else if (ch <= 0x7FF) {
            size += 2;
            i++;
        } else if (ch <= 0xD7FF || ch >= 0xE000) {
            // Regular BMP code point that is not a surrogate
            size += 3;
            i++;
        } else {
            // Surrogate range
            if (ch >= 0xD800 && ch <= 0xDBFF && i + 1 < end) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    // Valid surrogate pair => 4 bytes
                    size += 4;
                    i += 2;
                } else {
                    // Unpaired high surrogate, encode as 3 bytes
                    size += 3;
                    i++;
                }
            } else if (ch >= 0xDC00 && ch <= 0xDFFF) {
                // Unpaired low surrogate, encode as 3 bytes
                size += 3;
                i++;
            } else {
                // Should not happen, but fall back
                size += 3;
                i++;
            }
        }
    }
    return size;
}

