    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }

    int size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        int cp = Character.codePointAt(str, i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

