            index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
    List<E> edgeList = targetMap.computeIfAbsent(targetVertex, k -> new ArrayList<>());

    // Avoid duplicate entries
    if (!edgeList.contains(e)) {
        edgeList.add(e);
    }
}

