private void enlarge(final int size){
    // Validate input
    if (size < 0) {
        throw new IllegalArgumentException("Requested size must be non‑negative");
    }
    if (size == 0) {
        return; // nothing to do
    }

    // If the internal array is null (just in case), create it
    if (vector == null) {
        int initial = Math.max(1, size);
        vector = new byte[initial];
        len = 0;
        return;
    }

    // Compute the required capacity
    int required = len + size;
    if (required <= vector.length) {
        return; // current array big enough
    }

    // Grow the array: double until it is large enough
    int newCapacity = vector.length == 0 ? 1 : vector.length;
    while (newCapacity < required) {
        newCapacity <<= 1;       // double
        if (newCapacity < 0) {   // overflow protection
            newCapacity = required;
            break;
        }
    }

    // Allocate the larger array and copy existing data
    byte[] newVector = new byte[newCapacity];
    System.arraycopy(vector, 0, newVector, 0, len);
    vector = newVector;
}

