@Override
public int compare(Double o1, Double o2) {
    // Handle null values: consider null less than any non-null value
    if (o1 == null) {
        if (o2 == null) {
            return 0; // both null, considered equal
        } else {
            return -1; // null is less than non-null
        }
    }
    if (o2 == null) {
        return 1; // any non-null is greater than null
    }

    // Compare the non-null values
    double diff = o1 - o2;
    if (Double.isNaN(diff)) {
        // If either value is NaN, compare using Double.compareTo to adhere to contract
        int cmp = o1.compareTo(o2);
        if (cmp < 0) {
            return -1;
        } else if (cmp > 0) {
            return 1;
        } else {
            return 0;
        }
    } else if (diff < 0) {
        return -1;
    } else if (diff > 0) {
        return 1;
    } else {
        return 0;
    }
}

