public int compare(Double o1, Double o2) {
    if (o1 == null && o2 == null) {
        return 0;
    }
    if (o1 == null) {
        return -1;
    }
    if (o2 == null) {
        return 1;
    }
    int cmp = o1.compareTo(o2);
    return Integer.signum(cmp);
}

