@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or primitive char
    if (Character.class != type && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char, but was " + type);
    }

    // Null handling
    if (value == null) {
        if (type != Character.class) {
            // Primitive char cannot be null
            throw new IllegalArgumentException("Cannot convert null to primitive char");
        }
        return null; // Return null for Character
    }

    try {
        // Already a Character
        if (value instanceof Character) {
            return value;
        }

        // String of length 1
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            } else {
                throw new IllegalArgumentException("String length must be 1 to convert to Character");
            }
        }

        // Number converted via int value
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            return (char) intVal;
        }

        // Fallback: use toString() of the value and check length
        String text = value.toString();
        if (text.length() == 1) {
            return text.charAt(0);
        }

        throw new IllegalArgumentException("Cannot convert value of type " + value.getClass() + " to Character");
    } catch (Exception e) {
        // Wrap any runtime exception into the expected Exception
        throw new Exception("Conversion failed: " + e.getMessage(), e);
    }
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // If already a Character, just return it
    if (value instanceof Character) {
        return (Character) value;
    }
    // Convert from Number to a char code
    if (value instanceof Number) {
        int code = ((Number) value).intValue();
        return (char) code;
    }
    // Convert from CharSequence (String etc.) if length is 1
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        }
        throw new IllegalArgumentException(
            "Cannot convert CharSequence to Character: length != 1 (value=" + cs + ")");
    }
    // As a final attempt, use toString() and ensure length==1
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }
    throw new IllegalArgumentException(
        "Cannot convert value to Character (length != 1): " + value + " (" + str + ")");
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!java.lang.Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Target type must be java.lang.Character, found: " + type.getName());
    }

    // Handle null values
    if (value == null) {
        return null;
    }

    // Directly return Character instance
    if (value instanceof java.lang.Character) {
        return value;
    }

    // Convert from String of length 1
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new IllegalArgumentException("Cannot convert String of length >1 to Character: \"" + str + "\"");
        }
        return str.charAt(0);
    }

    // Convert from Number by casting to char code
    if (value instanceof Number) {
        try {
            int code = ((Number) value).intValue();
            return (char) code;
        } catch (Exception e) {
            throw new IllegalArgumentException("Failed to convert Number to Character: " + value, e);
        }
    }

    // Unsupported conversion
    throw new IllegalArgumentException("Unsupported conversion for type: " + value.getClass().getName());
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // The conversion is only applicable when the target type is Character
    if (!Character.class.equals(type)) {
        throw new IllegalArgumentException("Target type must be java.lang.Character");
    }

    // If the value is null, we simply return null (no conversion needed)
    if (value == null) {
        return null;
    }

    try {
        // If the value is already a Character, return it directly
        if (value instanceof Character) {
            return value;
        }

        // If the value is a String, ensure it has exactly one character and return that character
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            }
            throw new IllegalArgumentException(
                "Cannot convert String to Character: String must be 1 character long");
        }

        // If the value is a char (autoboxed), return it as Character
        if (value instanceof Character) {
            return value;
        }

        // For numeric types, interpret the value as a Unicode code point
        if (value instanceof Number) {
            int codePoint = ((Number) value).intValue();
            if (Character.isValidCodePoint(codePoint)) {
                return (char) codePoint;
            }
            throw new IllegalArgumentException(
                "Number value " + codePoint + " is not a valid Unicode code point for Character");
        }

        // For Boolean, convert true->'T', false->'F'
        if (value instanceof Boolean) {
            return ((Boolean) value) ? 'T' : 'F';
        }

        // Any other type cannot be converted to Character
        throw new IllegalArgumentException(
            "Cannot convert from type " + value.getClass().getName() + " to java.lang.Character");
    } catch (Exception ex) {
        // Wrap any exception that occurs during conversion
        throw new Exception("Conversion to java.lang.Character failed", ex);
    }
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Validate target type
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }
    if (!Character.class.equals(type) && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    // Handle null source
    if (value == null) {
        return null;
    }

    // Characters
    if (value instanceof Character) {
        char ch = (Character) value;
        return type == char.class ? ch : Character.valueOf(ch);
    }

    // Strings (first character)
    if (value instanceof String) {
        String str = (String) value;
        if (str.isEmpty()) {
            throw new Exception("Cannot convert empty string to Character");
        }
        char ch = str.charAt(0);
        return type == char.class ? ch : Character.valueOf(ch);
    }

    // Numbers (cast to char)
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        char ch = (char) intVal;
        return type == char.class ? ch : Character.valueOf(ch);
    }

    // Fallback: try to use the object's string representation
    String repr = value.toString();
    if (!repr.isEmpty()) {
        char ch = repr.charAt(0);
        return type == char.class ? ch : Character.valueOf(ch);
    }

    // If all conversions fail, throw an exception
    throw new Exception("Unable to convert " + value.getClass().getName() + " to Character");
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    if (str == null || searchStrArray == null) {
        return false;
    }
    if (searchStrArray.isEmpty()) {
        return false;
    }

    String lowerStr = str.toLowerCase(Locale.ROOT);

    for (String searchStr : searchStrArray) {
        if (searchStr == null || searchStr.isEmpty()) {
            continue;
        }
        String lowerSearch = searchStr.toLowerCase(Locale.ROOT);
        for (int i = 0; i < lowerSearch.length(); i++) {
            if (lowerStr.indexOf(lowerSearch.charAt(i)) >= 0) {
                return true;
            }
        }
    }
    return false;
}

