    // Handle null or empty inputs gracefully
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }

    // Convert the target string to lower case once for efficiency
    String lowerStr = str.toLowerCase();

    // Iterate over each search string, skipping null or empty values
    for (String search : searchStrArray) {
        if (search == null) {
            continue;
        }
        String lowerSearch = search.toLowerCase();
        if (lowerSearch.isEmpty()) {
            continue;
        }
        if (lowerStr.contains(lowerSearch)) {
            return true;
        }
    }

    // No match found
    return false;
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    // Defensive: if either argument is null or empty, nothing to search
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }

    // Build a set of all characters we need to look for, case‑insensitively
    java.util.Set<Character> searchChars = new java.util.HashSet<>();
    for (String search : searchStrArray) {
        if (search == null) continue;           // skip null elements
        for (int i = 0; i < search.length(); i++) {
            searchChars.add(Character.toLowerCase(search.charAt(i)));
        }
    }

    // If nothing was added (all search strings were null/empty), return false
    if (searchChars.isEmpty()) {
        return false;
    }

    // Scan the input string for any matching character
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (searchChars.contains(Character.toLowerCase(c))) {
            return true; // Found a match
        }
    }
    return false; // No match found
}

