        for (String search : searchStrArray) {
            if (search == null) {
                continue;
            }
            if (lowerStr.contains(search.toLowerCase())) {
                return true;
            }
        }
        return false;
    } catch (Exception e) {
        // In case of any runtime exception, gracefully return false
        return false;
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start with the next odd number >= desiredCapacity
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    int bound = desiredCapacity;
    if (desiredCapacity >= 1000) {
        // 11% above desiredCapacity
        bound = (int) (desiredCapacity * 111L / 100);
    }

    // Search within the bound first
    for (int n = candidate; n <= bound; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }

    // If no prime found within the bound, continue searching beyond it
    for (int n = bound + 1; ; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrt; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be positive");
    }
    // Special cases for small numbers
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity == 3) {
        return 3;
    }
    // Start from the next odd number >= desiredCapacity
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid integer overflow when incrementing
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new IllegalArgumentException("No prime found within integer range");
        }
        candidate += 2; // only test odd numbers
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrtN; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    // Handle non‑positive input by returning the smallest prime.
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Ensure candidate is odd (the only even prime is 2, which we already handled).
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++;
    }

    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid integer overflow when incrementing by 2.
        if (candidate > Integer.MAX_VALUE - 2) {
            // No larger prime exists within int range; fall back to max int.
            return Integer.MAX_VALUE;
        }
        candidate += 2;
    }
}

private static boolean isPrime(int number) {
    if (number < 2) {
        return false;
    }
    if (number == 2 || number == 3) {
        return true;
    }
    if ((number & 1) == 0) {
        return false;
    }

    // Use long to avoid overflow during the i*i comparison.
    long n = number;
    for (long i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    // Handle trivial cases and overflow
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Make the candidate odd (except for 2)
    if ((candidate & 1) == 0) {
        candidate++;
    }
    // Use long to avoid overflow when incrementing
    long longCand = candidate;
    while (true) {
        int candInt = (int) longCand;
        if (isPrime(candInt)) {
            return candInt;
        }
        longCand += 2; // Increment by 2 to stay odd
        // If we overflowed (candidate becomes negative) return Integer.MAX_VALUE which is prime
        if (longCand > Integer.MAX_VALUE) {
            return Integer.MAX_VALUE; // 2147483647 is prime
        }
    }
}

private static boolean isPrime(int n) {
    if (n < 2) return false;
    if (n == 2 || n == 3) return true;
    if ((n & 1) == 0) return false; // Even numbers greater than 2 are not prime
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrtN; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

