public static String trimTrailingWhitespace(String str){
    // Handle null or empty input
    if (str == null) {
        return null;
    }
    int length = str.length();
    if (length == 0) {
        return str;
    }

    // Find the index of the last non-whitespace character
    int lastNonWhiteIdx = length - 1;
    while (lastNonWhiteIdx >= 0 && Character.isWhitespace(str.charAt(lastNonWhiteIdx))) {
        lastNonWhiteIdx--;
    }

    // If all characters are whitespace, return empty string
    if (lastNonWhiteIdx < 0) {
        return "";
    }

    // Return substring up to the last non-whitespace character (inclusive)
    return str.substring(0, lastNonWhiteIdx + 1);
}

public static String trimTrailingWhitespace(String str){
    try {
        if (str == null) {
            return null;
        }
        int len = str.length();
        int end = len;
        while (end > 0 && Character.isWhitespace(str.charAt(end - 1))) {
            end--;
        }
        return str.substring(0, end);
    } catch (Exception e) {
        // In case of unexpected failures, return the original string
        return str;
    }
}

public void init() {
    try {
        // Attempt to retrieve the distribution path from a system property
        String distPath = System.getProperty("app.dist.path");

        // If not set via system property, try to load from a properties file
        if (distPath == null || distPath.isEmpty()) {
            java.util.Properties props = new java.util.Properties();
            java.io.InputStream in = getClass().getClassLoader().getResourceAsStream("config.properties");
            if (in != null) {
                try {
                    props.load(in);
                } finally {
                    in.close();
                }
                distPath = props.getProperty("dist.path");
            }
        }

        // Validate the distribution path
        if (distPath == null || distPath.isEmpty()) {
            throw new IllegalStateException("Distribution path is not defined in system properties or config file.");
        }

        java.io.File distDir = new java.io.File(distPath);
        if (!distDir.exists()) {
            // Attempt to create the directory if it does not exist
            if (!distDir.mkdirs()) {
                throw new java.io.IOException("Failed to create distribution directory: " + distPath);
            }
