private int removeUnusedNodesFromNode(Category node) {
    int count = 0;
    if (node == null || node.children == null) {
        return 0;
    }
    for (java.util.Iterator<Category> it = node.children.iterator(); it.hasNext(); ) {
        Category child = it.next();
        if (child == null) {
            continue;
        }
        if (!child.active) {
            it.remove();
            count += 1;
        } else {
            count += removeUnusedNodesFromNode(child);
        }
    }
    return count;
}

