        }
        // Ensure indices are sorted before checking continuity.
        java.util.Arrays.sort(indices);
        for (int i = 0; i < indices.length - 1; i++) {
            if (indices[i] + 1 != indices[i + 1]) {
                throw new IllegalStateException(
                    "Sharding key indices are not continuous for model: " + modelName
                    + ". Gap found between indices " + indices[i] + " and " + indices[i + 1]
                );
            }
        }
    } catch (IllegalStateException e) {
        throw e; // rethrow known state exceptions
    } catch (Exception e) {
        // Wrap any unexpected exception in an IllegalStateException.
        throw new IllegalStateException(
            "Failed to check sharding key indices for model: " + modelName, e
        );
    }
}

private void check(String modelName) throws IllegalStateException {
