    }

    // Ensure the indices are sorted in ascending order and continuous without gaps.
    indices.sort(Integer::compareTo); // sort in place
    for (int i = 0; i < indices.size(); i++) {
        int expectedIndex = i; // continuous sequence starting from 0
        int actualIndex = indices.get(i);
        if (actualIndex != expectedIndex) {
            throw new IllegalStateException(
                "Sharding key indices for model '" + modelName + "' are not continuous. "
                + "Expected index " + expectedIndex + " but found " + actualIndex + ".");
        }
    }
}

