        }
        java.util.List<ShardingKey> keys = meta.getShardingKeys();
        if (keys == null || keys.isEmpty()) {
            return; // nothing to check
        }
        keys.sort(java.util.Comparator.comparingInt(ShardingKey::getIndex));
        int prevIndex = -1;
        for (ShardingKey key : keys) {
            int idx = key.getIndex();
            if (prevIndex != -1 && idx != prevIndex + 1) {
                throw new IllegalStateException(
                        "Sharding key indices are not continuous for model: " + modelName +
                        ". Gap detected between indices " + prevIndex + " and " + idx);
            }
            prevIndex = idx;
        }
    } catch (IllegalStateException e) {
        throw e;
    } catch (Exception e) {
        throw new IllegalStateException(
                "Failed to validate sharding key indices for model: " + modelName, e);
    }
