        }

        if (transportObj != null) {
            // Handle String representations
            if (transportObj instanceof String) {
                String transport = (String) transportObj;
                if ("http".equalsIgnoreCase(transport) || "sse".equalsIgnoreCase(transport)) {
                    // Suspend with default configuration
                    r.suspend();
                } else if ("websocket".equalsIgnoreCase(transport)) {
                    // WebSocket typically remains open; safe to suspend if needed.
                    r.suspend();
                }
            } else {
                // Handle enum representations (e.g., AtmosphereResource.TRANSPORT.X)
                try {
                    // Attempt to call enum name() if supported
                    String name = transportObj.toString();
                    if ("HTTP".equalsIgnoreCase(name) || "SSE".equalsIgnoreCase(name)
                            || "WEBSOCKET".equalsIgnoreCase(name)) {
                        r.suspend();
                    }
                } catch (Exception ignored) {
                    // ignore any reflection or conversion errors
                }
            }
        }
    } catch (Exception e) {
        // Any exception during suspension is ignored so that processing can continue.
    }

    // Return CONTINUE to allow the Atmosphere framework to proceed with its chain.
    return Action.CONTINUE;
}

