        // For collision resolution assumptions similar to java.util.HashMap
        int index = (this.table.length - 1) & h;

        // Traverse the bucket linked list looking for a matching key
        for (Entry entry = this.table[index]; entry != null; entry = entry.next) {
            if (entry.hash == h && (key == entry.key || key.equals(entry.key))) {
                return true;
            }
        }
        return false;
    } catch (Throwable t) {
        // Any unexpected runtime issues are wrapped in an unchecked exception
        throw new RuntimeException("containsKey failed for key: " + key, t);
    }
