protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        // return an empty path
        return new DefaultGraphPath<>(graph, new LinkedList<>(), new LinkedList<>());
    }

    // Copy the set to work on
    Set<E> remaining = new HashSet<>(tour);
    Iterator<E> it = remaining.iterator();
    E startEdge = it.next();
    it.remove();

    // Determine the starting vertex sequence
    V startVertex = graph.getEdgeSource(startEdge);
    V nextVertex = graph.getEdgeTarget(startEdge);

    List<V> vertices = new LinkedList<>();
    List<E> edges = new LinkedList<>();

    vertices.add(startVertex);
    vertices.add(nextVertex);
    edges.add(startEdge);

    V lastVertex = nextVertex;

    // Build path by following edges that connect to the last vertex
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> remIt = remaining.iterator();
        while (remIt.hasNext()) {
            E e = remIt.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(lastVertex) || tgt.equals(lastVertex)) {
                // Edge connects to the last vertex; add the next vertex
                V following = src.equals(lastVertex) ? tgt : src;
                edges.add(e);
                vertices.add(following);
                lastVertex = following;
                remIt.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            // The edges do not form a single connected path
            throw new IllegalArgumentException("The provided edge set does not form a connected tour");
        }
    }

    return new DefaultGraphPath<>(graph, vertices, edges);
}

