        }
        int n = bounds.size();
        List<Integer> suffix = new ArrayList<>(n);
        long total = 0L;
        for (Integer val : bounds) {
            if (val == null) {
                throw new IllegalArgumentException("bounds list contains null");
            }
            total += val;
        }
        long running = 0L;
        int[] res = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            running += bounds.get(i);
            res[i] = (int) running;
        }
        for (int val : res) {
            suffix.add(val);
        }
        return new Pair<>(suffix, total);
    } catch (Exception e) {
        throw new RuntimeException("Error computing suffix sum", e);
    }
}

