private void moveAllListNodes(DoublyLinkedList<E> list) {
    /* Move every node from *list* into *this*.  This is implemented by
     * splicing the two internal node chains together in constant time.
     * The implementation assumes that the internal fields of the
     * DoublyLinkedList are:
     *   - firstNode (the first real node, or null if the list is empty)
     *   - lastNode  (the last real node, or null if the list is empty)
     *   - nodeCount (number of nodes in the list)
     *   - ListNodeImpl<E> has public fields 'prev' and 'next'.
     *
     *  If *list* is null, the same instance, or empty this method
     *  simply returns.  All manipulations are guarded by a small
     *  try/catch to convert unexpected exceptions into a RuntimeException
     *  with a helpful message.
     */
    if (list == null || list == this) {
        return;
    }

    try {
        // Source list first and last nodes
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> srcFirst = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .get(list);
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> srcLast = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .get(list);

        if (srcFirst == null) {          // source list empty
            return;
        }

        // Destination list fields
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> destFirst = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .get(this);
        @SuppressWarnings("unchecked")
        ListNodeImpl<E> destLast = (ListNodeImpl<E>) java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .get(this);
        int srcSize = (int) java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .getInt(list);
        int destSize = (int) java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .getInt(this);

        /* Splice source list after destination tail if destination is
         * non-empty; otherwise make source the new list. */
        if (destLast != null) {
            destLast.next = srcFirst;
            srcFirst.prev = destLast;
            destLast = srcLast;
        } else {
            destFirst = srcFirst;
            destLast = srcLast;
        }

        // Update destination list fields
        java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .set(this, destFirst);
        java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .set(this, destLast);
        java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .setInt(this, destSize + srcSize);

        // Clear source list
        java.lang.reflect.Field.class
                .getDeclaredField("firstNode")
                .set(list, null);
        java.lang.reflect.Field.class
                .getDeclaredField("lastNode")
                .set(list, null);
        java.lang.reflect.Field.class
                .getDeclaredField("nodeCount")
                .setInt(list, 0);
    } catch (Exception e) {
        throw new RuntimeException("Unable to move list nodes", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("list");
    }
    // Moving nodes from a list to itself has no effect
    if (list == this) {
        return;
    }
    try {
        // Continue until the source list is empty
        while (list.size() > 0) {
            // Retrieve the first node of the source list
            ListNodeImpl<E> node = list.head; // head is accessible because it belongs to the same class
            if (node == null) {
                break; // defensive: should not happen when size > 0
            }
            // Remove the node from the source list
            list.removeListNode(node);
            // Add the node to this list
            this.addListNode(node);
        }
    } catch (RuntimeException e) {
        // If any unexpected runtime exception occurs, rethrow with context
        throw new RuntimeException("Failed to move all list nodes", e);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new NullPointerException("Source list cannot be null");
    }
    if (list == this) {
        return;
    }
    // Iterate over the source list. Preserve the next node reference before removal.
    ListNodeImpl<E> current = list.head; // assume field name 'head'
    while (current != null) {
        ListNodeImpl<E> next = current.next; // preserve next pointer
        list.removeListNode(current);
        this.addListNode(current);
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list must not be null");
    }
    if (list == this) {
        // nothing to do
        return;
    }
    // iterate over all nodes in the source list
    ListNode<E> current = list.head; // private field is accessible within the same class
    while (current != null) {
        // remember the next node before we modify the structure
        ListNode<E> next = current.next;
        try {
            list.removeListNode(current);
            this.addListNode(current);
        } catch (RuntimeException ex) {
            // stop further processing and propagate the error
            throw new RuntimeException("Failed to move node during moveAllListNodes", ex);
        }
        current = next;
    }
}

