    if (str == null) {
        return prefix == null;
    }
    // If the prefix is null but the string isn't, it can't start with null
    if (prefix == null) {
        return false;
    }
    // An empty prefix always matches
    if (prefix.isEmpty()) {
        return true;
    }

    if (ignoreCase) {
        // regionMatches will handle length checks internally
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
