public void putAllWriteable(BeanMap map) {
    if (map == null) return;

    PropertyDescriptor[] srcDescs;
    try {
        srcDescs = map.getDescriptors();
    } catch (Exception e) {
        // If we cannot retrieve descriptors, nothing to do
        return;
    }

    for (PropertyDescriptor srcDesc : srcDescs) {
        // Skip if source property is not readable (write-only)
        if (!srcDesc.isReadable()) {
            continue;
        }

        Object value;
        try {
            value = map.get(srcDesc.getName());
        } catch (Exception e) {
            // Unable to read the value, skip this property
            continue;
        }

        try {
            // Attempt to write into the current BeanMap
            this.set(srcDesc.getName(), value);
        } catch (Exception e) {
            // Property might be read‑only or not exist in this BeanMap – ignore
        }
    }
}

