public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Validate input
    if (table == null || pane == null) {
        return; // nothing to do
    }

    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return; // out of bounds, avoid index exception
    }

    // Use Swing EDT to perform UI updates safely
    SwingUtilities.invokeLater(() -> {
        // Select the specified row
        table.setRowSelectionInterval(row, row);

        // Scroll the table to make the row visible
        Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            table.scrollRectToVisible(cellRect);
        }

        // Repaint after a short delay to ensure the new selection is rendered.
        // The timer mimics a delayed repaint (e.g., 50 ms) which is usually enough for the UI to update.
        new javax.swing.Timer(50, e -> {
            table.repaint();
            ((javax.swing.Timer) e.getSource()).stop();
        }).start();
    });
}

