public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    // Assume the full name is stored in a field called 'name'.
    final String fullName = this.name;
    if (fullName == null || fullName.isEmpty()) {
        return; // nothing to abbreviate
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart must be non‑negative");
    }
    if (nameStart >= fullName.length()) {
        return; // start index beyond end of name
    }

    String sub = fullName.substring(nameStart);
    boolean newWord = true;
    for (int i = 0; i < sub.length(); i++) {
        char ch = sub.charAt(i);
        if (Character.isWhitespace(ch) || ch == '.') {
            newWord = true; // next non‑space or non‑dot starts a new word
        } else if (newWord) {
            buf.append(Character.toUpperCase(ch)); // first letter of a word
            newWord = false;
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        return;
    }
    try {
        if (nameStart < 0 || nameStart > buf.length()) {
            return;
        }
        String remaining = buf.substring(nameStart).trim();
        if (remaining.isEmpty()) {
            return;
        }
        String[] parts = remaining.split("\\s+");
        StringBuilder abbrev = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            String part = parts[i];
            if (!part.isEmpty()) {
                abbrev.append(Character.toUpperCase(part.charAt(0))).append('.');
                if (i < parts.length - 1) {
                    abbrev.append(' ');
                }
            }
        }
        if (abbrev.length() > 0) {
            buf.append(abbrev);
        }
    } catch (RuntimeException e) {
        // Suppress to avoid propagating runtime issues
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Validate buffer
    if (buf == null) {
        throw new NullPointerException("StringBuffer 'buf' must not be null");
    }
    // Basic sanity for nameStart
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart (" + nameStart + ") must be non‑negative");
    }
    // Retrieve the full name from the enclosing instance
    final String fullName = this.name;   // assumes a field named 'name' exists
    if (fullName == null) {
        throw new IllegalStateException("Name has not been initialized");
    }
    // Ensure the start index does not exceed the string length
    if (nameStart > fullName.length()) {
        throw new IllegalArgumentException(
                "nameStart (" + nameStart + ") exceeds name length (" + fullName.length() + ")");
    }
    // If nameStart is at the end of the string, there is nothing to abbreviate
    if (nameStart == fullName.length()) {
        return;
    }

    // Substring of the name to abbreviate
    final String remaining = fullName.substring(nameStart);

    // Split on common delimiters (dot, slash, underscore)
    final String[] parts = remaining.split("[\\.\\/_-]");

    // Append the first character of each segment, separated by dots
    for (int i = 0, n = parts.length; i < n; i++) {
        if (!parts[i].isEmpty()) {
            buf.append(parts[i].charAt(0));
        }
        if (i < n - 1) {
            buf.append('.');
        }
    }
}

