private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int idx = 0;
    // If a method descriptor, skip the argument part and ignore the return type
    if (descriptor.charAt(0) == '(') {
        idx = 1;
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            idx = popComponent(descriptor, idx);
        }
        // Skip the ')' character. Return type is ignored.
        // No further actions needed; the method simply returns.
    } else {
        popComponent(descriptor, idx);
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }

    // Helper lambda to pop the appropriate number of slots for a single type
    java.util.function.Consumer<Integer> popSlots = count -> {
        for (int i = 0; i < count; i++) {
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Stack underflow while popping descriptor");
            }
            outputFrameStack.pop();
        }
    };

    // Common parsing loop for argument- or type-descriptors
    java.util.function.Consumer<String> parseDescriptor = typeStr -> {
        int i = 0;
        int len = typeStr.length();
        while (i < len) {
            // Skip any array brackets
            while (i < len && typeStr.charAt(i) == '[') {
                i++;
            }
            if (i >= len) {
                break;
            }
            char type = typeStr.charAt(i);
            int slots = 1; // default one slot
            if (type == 'J' || type == 'D') { // long or double occupy two slots
                slots = 2;
                i++; // consume the type char
            } else if (type == 'L') { // object type ends with ';'
                int semicolon = typeStr.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' in object type");
                }
                i = semicolon + 1; // consume up to and including ';'
            } else if (type == 'Z' || type == 'B' || type == 'C'
                    || type == 'S' || type == 'I' || type == 'F') {
                i++; // consume primitive type
            } else {
                throw new IllegalArgumentException("Unrecognized type descriptor: " + type);
            }
            popSlots.accept(slots);
        }
    };

    // If the descriptor is a method descriptor handle only arguments
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        int close = descriptor.indexOf(')');
        if (close == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String args = descriptor.substring(1, close);
        parseDescriptor.accept(args);
    } else { // normal type descriptor
        parseDescriptor.accept(descriptor);
    }
}

