    if (keys == null || keys.isEmpty()) {
        return result;
    }
    // Convert to Integer list, skipping nulls and non-Integer values
    List<Integer> intKeys = new ArrayList<>();
    for (K k : keys) {
        if (k == null) {
            continue;
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("Key must be an Integer");
        }
        intKeys.add((Integer) k);
    }
    if (intKeys.isEmpty()) {
        return result;
    }
    // Sort and keep unique values
    Set<Integer> uniqueSet = new TreeSet<>(intKeys);
    List<Integer> sortedUnique = new ArrayList<>(uniqueSet);
    // For each original key, find the next greater value
    for (Integer key : intKeys) {
        int idx = Collections.binarySearch(sortedUnique, key);
        if (idx < 0) {
            // This should not happen because key is in uniqueSet
            idx = -idx - 1;
        }
        idx++; // move to next greater element
        if (idx < sortedUnique.size()) {
            result.add(sortedUnique.get(idx));
        } else {
            // No greater element found, use a sentinel value
            result.add(Integer.MAX_VALUE);
        }
    }
