static String[] toNoNullStringArray(Object[] array){
    // Handle null input
    if (array == null) {
        return new String[0];
    }

    int length = array.length;
    int nullCount = 0;

    // Count nulls
    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        }
    }

    // No nulls – return original if it is already a String[].  
    if (nullCount == 0) {
        if (array.getClass().getComponentType() == String.class) {
            return (String[]) array;
        } else {
            // Convert all elements to String (unlikely but safe)
            String[] result = new String[length];
            for (int i = 0; i < length; i++) {
                result[i] = array[i].toString();
            }
            return result;
        }
    }

    // Build a new array without nulls
    String[] clean = new String[length - nullCount];
    int dest = 0;
    for (Object obj : array) {
        if (obj != null) {
            clean[dest++] = obj instanceof String ? (String) obj : obj.toString();
        }
    }
    return clean;
}

