public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Null checks – if either sequence is null, no match can exist
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subLen = substring.length();

    // Empty substring matches at any position between 0 and strLen (inclusive)
    if (subLen == 0) {
        return index >= 0 && index <= strLen;
    }

    // Index must be valid and the substring must fit in the remaining part of str
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

