                break;
            } catch (ClassNotFoundException cnf) {
                throw new IOException("Failed to deserialize ThreadSnapshot", cnf);
            }
        }
    } catch (IOException e) {
        // Rethrow to inform caller of I/O problems
        throw new IOException("Error reading thread snapshots from file: " + e.getMessage(), e);
    }

    // Filter snapshots according to the specified time ranges
    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        long timestamp = 0L;
        try {
            // Assume ThreadSnapshot has a method getTimestamp() that returns a long
            timestamp = snapshot.getTimestamp();
        } catch (Exception e) {
            // Skip any snapshot that does not expose a timestamp
            continue;
        }

        for (ProfileAnalyzeTimeRange range : timeRanges) {
            long start = 0L;
            long end = 0L;
            try {
                // Assume ProfileAnalyzeTimeRange exposes getStartTime() and getEndTime()
                start = range.getStartTime();
                end = range.getEndTime();
            } catch (Exception e) {
                // Skip ranges that do not expose times correctly
                continue;
            }

            if (timestamp >= start && timestamp <= end) {
                result.add(snapshot);
                break; // No need to test against remaining ranges
            }
        }
    }

    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                // Assume ThreadSnapshot has a static method `parse` that returns an instance from a string representation.
                ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
                if (snapshot == null) {
                    continue;
                }
                long ts = snapshot.getTimestamp(); // Assume a method that gives the snapshot's timestamp.
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                        result.add(snapshot);
                        break;
                    }
                }
            } catch (Exception e) {
                // Ignore malformed lines but log if needed.
                continue;
            }
        }
    }
    return result;
}
